// Regenerates src/data/countries.js from the public `world-countries` dataset.
//
//   curl -sLO https://unpkg.com/world-countries@5.1.0/countries.json
//   node scripts/gen-countries.mjs ./countries.json
//
// The generated file is committed, so the dataset is only needed when the list
// has to be refreshed.
import { readFileSync, writeFileSync } from "node:fs";

const source = process.argv[2] || "./countries.json";
const countries = JSON.parse(readFileSync(source, "utf8"));

// Our six map windows. `world-countries` splits the Americas by subregion.
const continentOf = (c) => {
  if (c.region === "Americas")
    return c.subregion === "South America" ? "south-america" : "north-america";
  if (c.region === "Africa") return "africa";
  if (c.region === "Europe") return "europe";
  if (c.region === "Asia") return "asia";
  if (c.region === "Oceania") return "oceania";
  return "world";
};

// Territories are kept — Hong Kong, Gibraltar and the like are real trips.
const rows = countries
  .map((c) => ({
    code: c.cca2,
    ccn3: c.ccn3,
    name: c.translations?.rus?.common || c.name.common,
    nameEn: c.name.common,
    continent: continentOf(c),
    // [lon, lat], used to centre the map and to pin countries too small to draw.
    lonlat: [Number(c.latlng[1].toFixed(2)), Number(c.latlng[0].toFixed(2))],
  }))
  .sort((a, b) => a.name.localeCompare(b.name, "ru"));

const body = rows
  .map(
    (r) =>
      `  { code: ${JSON.stringify(r.code)}, ccn3: ${JSON.stringify(r.ccn3)}, ` +
      `name: ${JSON.stringify(r.name)}, nameEn: ${JSON.stringify(r.nameEn)}, ` +
      `continent: ${JSON.stringify(r.continent)}, lonlat: ${JSON.stringify(r.lonlat)} },`
  )
  .join("\n");

writeFileSync(
  new URL("../src/data/countries.js", import.meta.url),
  `// Generated by scripts/gen-countries.mjs — do not edit by hand.\n` +
    `// code: ISO 3166-1 alpha-2 · ccn3: numeric id, matches the map topology.\n` +
    `export const COUNTRIES = [\n${body}\n];\n`
);

console.log(`wrote ${rows.length} countries`);
